import{c as t,Q as a,j as o,m as n}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse(`{"title":"Claude Code Dynamic Workflows: What's Actually Changed","description":"","frontmatter":{},"headers":[],"relativePath":"research/tweets/2026-06-08-@samueljmcd-825416.md","filePath":"research/tweets/2026-06-08-@samueljmcd-825416.md","lastUpdated":1785909234000}`),i={name:"research/tweets/2026-06-08-@samueljmcd-825416.md"};function r(s,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="claude-code-dynamic-workflows-what-s-actually-changed" tabindex="-1">Claude Code Dynamic Workflows: What&#39;s Actually Changed <a class="header-anchor" href="#claude-code-dynamic-workflows-what-s-actually-changed" aria-label="Permalink to &quot;Claude Code Dynamic Workflows: What&#39;s Actually Changed&quot;">​</a></h1><p><strong>作者</strong>：Samuel McDonnell (@samueljmcd)<br><strong>發布時間</strong>：2026-06-08<br><strong>原始連結</strong>：<a href="https://x.com/samueljmcd/status/2064078883318825416" target="_blank" rel="noreferrer">https://x.com/samueljmcd/status/2064078883318825416</a><br><strong>類型</strong>：Twitter Article<br><strong>統計</strong>：❤️ 89 · 🔁 7 · 🔖 178 · 👁 12,260</p><hr><h2 id="分析摘要" tabindex="-1">分析摘要 <a class="header-anchor" href="#分析摘要" aria-label="Permalink to &quot;分析摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：Dynamic Workflows 深度技術分析：orchestration script 內部機制、真實 token economics（每 subagent 各自 context window + verification 層 = 2N 費用）、三種呼叫模式（/deep-research、Claude workflow、/effort ultracode）、以及關鍵決策準則「任務 scope 超出單一 agent 且可分解為可獨立驗證子任務才用 workflow」。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>執行模型根本性轉變</strong>：Claude 生成一個 JavaScript orchestration script 描述任務分解，然後執行 script 以 parallel subagents 運行，每個 subagent 有乾淨 scoped context；intermediate results 存在 script 變數中，不污染主 context</li><li><strong>「16-wide pipe」vs 「1,000 parallel」</strong>：實際上是 16 concurrent subagents + 1,000 total per run；不是無限並行，是固定寬度的 pipe</li><li><strong>Verification layer 才是有趣之處</strong>：允許一個 subagent adversarially challenge 另一個 subagent 的 output；核心原因：clean context 的 reviewer 不帶 original agent 的 running justifications，不會 rationalize 壞步驟；重要 caveat：兩個 agent 同模型共享 blind spots，不是真正獨立</li><li><strong>Token economics 誠實版本</strong>：N 個 subagents = N 個 independent context window completions；加 verification = 2N；不要把 <code>/effort ultracode</code> 留作 default</li><li><strong>三種呼叫模式</strong>：(1) <code>/deep-research</code>（最低摩擦，適合資訊收集）；(2) 要求 Claude 建立 workflow（技術任務推薦，精確定義 scope/output/validation/editing policy）；(3) <code>/effort ultracode</code>（自動決策 workflow，成本不可預測）</li><li><strong>工程架構訊號</strong>：Orchestration script 可儲存為 <code>.claude/workflows/</code> custom command，實現 repeatability——可排程跑在下季 codebase 的 executable spec</li></ol><h3 id="關鍵引語" tabindex="-1">關鍵引語 <a class="header-anchor" href="#關鍵引語" aria-label="Permalink to &quot;關鍵引語&quot;">​</a></h3><blockquote><p>&quot;The failure mode in single-agent LLM work is confident plausibility: the model produces something that looks right and passes surface checks, but has quietly introduced a regression or made a bad assumption in step 14 of 30.&quot;</p></blockquote><blockquote><p>&quot;Dynamic Workflows is what you use when you&#39;ve identified a task that&#39;s genuinely too wide for one agent to hold coherently, and you&#39;ve been precise enough about the success criteria that a verification agent can actually do its job. Everything else is just expensive theatre.&quot;</p></blockquote><h3 id="決策準則" tabindex="-1">決策準則 <a class="header-anchor" href="#決策準則" aria-label="Permalink to &quot;決策準則&quot;">​</a></h3><p>任務應滿足：(1) scope 超出單一 agent 可連貫持有 + (2) 可分解為 independently verifiable subtasks</p><table tabindex="0"><thead><tr><th>適合</th><th>不適合</th></tr></thead><tbody><tr><td>Codebase-wide security audit</td><td>Bug fix in single file</td></tr><tr><td>Large-scale migration (per-file pass/fail)</td><td>Architecture / open-ended exploration</td></tr><tr><td>Multi-source investigation</td><td>Writing tests for new module</td></tr><tr><td>Deprecation sweep (embarrassingly parallel)</td><td>無明確 validation criterion 的任務</td></tr></tbody></table><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li>作者是 Dublin AI engineer，非 Anthropic 官方，但技術分析品質高</li><li>&quot;Confident plausibility&quot; failure mode 命名清晰、可記憶、可複用</li><li>「clean context reviewer 仍共享 blind spots」的 caveat 是許多教程遺漏的</li><li>將 workflow 視為 infrastructure（<code>.claude/workflows/</code> 可版本化執行 spec）的角度很有遠見</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>理由</th></tr></thead><tbody><tr><td>A. Workspace 可行動性</td><td>8/10</td><td>三種呼叫模式 + 決策準則 + ultracode 警告全可立即套用</td></tr><tr><td>B. 創新性</td><td>7/10</td><td>&quot;confident plausibility&quot; 命名 + workflow-as-infrastructure 角度 + reviewer caveat 是新見解</td></tr><tr><td>C. 證據品質</td><td>8/10</td><td>引用 Anthropic docs，有個人 production system 接地；決策準則基於 token economics 推導</td></tr><tr><td>D. 技術深度</td><td>9/10</td><td>orchestration script 內部機制、16-wide pipe 澄清、2N token 計算、三模式差異最深入</td></tr><tr><td>E. 泛化性</td><td>8/10</td><td>決策準則 + confident plausibility 命名可泛化至任何 multi-agent orchestration</td></tr><tr><td><strong>加權總分</strong></td><td><strong>7.95/10</strong></td><td>A×0.3 + B×0.2 + C×0.2 + D×0.15 + E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule<br><strong>整合位置</strong>：<code>subagent-strategy.md</code>：workflow 使用決策準則 + &quot;confident plausibility&quot; 命名 + reviewer caveat（同模型共享 blind spots）；<code>context-management.md</code>：ultracode 不留作 default + 2N token economics<br><strong>整合狀態</strong>：待實作</p><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Anthropic announced Dynamic Workflows for Claude Code on June 2nd, and the coverage has been predictably breathless. &quot;Complete quarterly tasks in days.&quot; &quot;Up to 1,000 parallel subagents.&quot; That kind of thing.</p><p>The capability is real and it&#39;s a meaningful architectural shift. But the framing in most writeups skips past the parts that actually matter for anyone building production systems: how orchestration works under the hood, what it costs, and when it&#39;s a bad idea.</p><h2 id="what-s-actually-new-here" tabindex="-1">What&#39;s Actually New Here <a class="header-anchor" href="#what-s-actually-new-here" aria-label="Permalink to &quot;What&#39;s Actually New Here&quot;">​</a></h2><p>Classic Claude Code is fundamentally sequential: one context window, one thread of reasoning, tasks executed turn-by-turn. That works fine for a focused coding session. It falls apart at scale, on jobs like auditing 400 routes, porting a large codebase, or running a multi-source investigation, because the single context either overflows or loses coherence across a long chain of steps.</p><p>Dynamic Workflows solves this with a different execution model. Instead of Claude reasoning inside a single context, it generates a JavaScript orchestration script that describes the task decomposition, then executes that script with subagents running in parallel, each subagent getting a clean, scoped context. Intermediate results live inside the script&#39;s variables rather than in Claude&#39;s context window, so they&#39;re aggregated at the end without ever polluting the main thread.</p><p>&quot;Parallel&quot; has a ceiling worth knowing. The runtime caps a run at 16 subagents running concurrently and 1,000 total per run. So the work is wide, not infinite, and the breathless &quot;1,000 parallel&quot; framing is really 1,000 dispatched across a 16-wide pipe.</p><p>The generated orchestration script is inspectable before execution. You can read the decomposition logic and approve the plan before committing tokens to it. That&#39;s the right default. Don&#39;t skip it.</p><h2 id="the-verification-layer-is-the-actually-interesting-part" tabindex="-1">The Verification Layer Is The Actually Interesting Part <a class="header-anchor" href="#the-verification-layer-is-the-actually-interesting-part" aria-label="Permalink to &quot;The Verification Layer Is The Actually Interesting Part&quot;">​</a></h2><p>Parallel execution of subagents is not new ground. Any orchestration framework can do that. What makes this worth paying attention to is the built-in verification pattern.</p><p>Anthropic&#39;s design explicitly allows one subagent to review or adversarially challenge another&#39;s output. For an AI system working on a large codebase, this matters a lot. The failure mode in single-agent LLM work is confident plausibility: the model produces something that looks right and passes surface checks, but has quietly introduced a regression or made a bad assumption in step 14 of 30.</p><blockquote><p>The failure mode in single-agent LLM work is confident plausibility. A reviewer spawned from a clean context doesn&#39;t carry the original agent&#39;s running justifications, so it&#39;s far less likely to rationalise a bad step into a good one.</p></blockquote><p>That&#39;s a real improvement over post-hoc self-review, where the model re-reads its own reasoning and agrees with itself.</p><p>This has a ceiling. Both agents are the same model with the same training, so they share the same blind spots. A clean context removes the local bias that weakens self-review. It does not give you an independent second opinion. Treat the reviewer as a strong check, not an oracle.</p><h2 id="token-economics-the-honest-version" tabindex="-1">Token Economics: The Honest Version <a class="header-anchor" href="#token-economics-the-honest-version" aria-label="Permalink to &quot;Token Economics: The Honest Version&quot;">​</a></h2><p>Anthropic&#39;s own docs flag that dynamic workflows &quot;consume significantly more tokens than a typical Claude Code session.&quot; That&#39;s underselling it.</p><p>Each subagent gets its own context window. That&#39;s the whole point of avoiding context overflow, but it means you&#39;re paying for N independent completions rather than one. Add a verification layer on top, and you&#39;re paying 2N. Add the aggregation step. It compounds fast.</p><p><code>/effort ultracode</code> is the mode where Claude decides for itself whether a task warrants a workflow. It combines xhigh reasoning with automatic orchestration and lasts for the session. Leaving it on for routine work is how you get a very unpleasant invoice at the end of the month. Drop back to <code>/effort high</code> once the heavy task is done.</p><h2 id="three-invocation-patterns" tabindex="-1">Three Invocation Patterns <a class="header-anchor" href="#three-invocation-patterns" aria-label="Permalink to &quot;Three Invocation Patterns&quot;">​</a></h2><ol><li><p><strong><code>/deep-research</code> (built-in workflow)</strong>. Lowest friction. Runs a multi-agent research sweep with cross-verification and returns a cited report. The orchestration is opaque; you don&#39;t write the decomposition. Fine for information gathering where the cost of a wrong decomposition is low. Not what you want for production code changes.</p></li><li><p><strong>Asking Claude to create a workflow</strong>. This is the one you actually want for technical tasks. You ask Claude to run a workflow and you write the scope, the expected output format, the validation criteria, and the editing policy explicitly in the prompt. The orchestrator generates a script from that spec, which you approve before anything runs.</p><p>The quality of the generated script is directly proportional to how precisely you define those parameters. &quot;Improve the auth layer&quot; will produce a decomposition that diverges and wastes tokens. &quot;Audit X, output Y, validation rule Z, no file modifications&quot; gives the orchestrator something to work with.</p></li><li><p><strong><code>/effort ultracode</code></strong>. Automated orchestration mode. Claude decides when to invoke workflows. High inference, high token burn, lowest manual control. Useful when you want to throw a genuinely large task at it and not micromanage the decomposition. The tradeoff is that cost predictability goes out the window.</p></li></ol><h2 id="when-to-actually-use-it" tabindex="-1">When To Actually Use It <a class="header-anchor" href="#when-to-actually-use-it" aria-label="Permalink to &quot;When To Actually Use It&quot;">​</a></h2><p>The honest decision rule is: does this task require broader scope than one agent can hold coherently, and is it decomposable into independently verifiable subtasks?</p><p>The tasks where this genuinely shines share a structure: the work is wide, the subtasks are independent, and success has a clear definition the verification agent can check against. The moment you&#39;re in territory where reasonable engineers would disagree on what &quot;done&quot; looks like, dynamic workflows will burn tokens and produce noise.</p><h2 id="what-this-actually-signals-architecturally" tabindex="-1">What This Actually Signals Architecturally <a class="header-anchor" href="#what-this-actually-signals-architecturally" aria-label="Permalink to &quot;What This Actually Signals Architecturally&quot;">​</a></h2><p>The more interesting read on this feature isn&#39;t &quot;Claude Code can now do bigger tasks.&quot; It&#39;s that Anthropic is shifting the product model for Claude Code from conversational assistant to workflow runtime.</p><p>The generated JavaScript script is the key artefact here. The orchestration logic is inspectable, auditable, and already saveable: a finished run can be written to <code>.claude/workflows/</code> as a custom command and re-run on any branch or project. That&#39;s a fundamentally different thing from a chat history. It&#39;s an executable spec of how to decompose a class of task.</p><p>That matters because repeatability is where AI tooling in production actually earns its keep. A one-off answer from a chat session is hard to operationalise. A versioned orchestration script that you can run against next quarter&#39;s codebase is infrastructure.</p><blockquote><p>Practical takeaway: for teams running regular codebase hygiene tasks like auth audits, deprecation sweeps, and test-coverage gaps, dynamic workflows are worth evaluating as a scheduled job rather than an ad-hoc tool. The ROI calculation changes significantly when you&#39;re amortising the token cost over repeated execution of a stable script.</p></blockquote><blockquote><p>Watch out for: vague task specs, /effort ultracode left on as default, and using workflows for tasks with no clear validation criterion. These are the three ways to burn a lot of money and get plausible-looking output that you can&#39;t actually trust.</p></blockquote><p>Dynamic Workflows is what you use when you&#39;ve identified a task that&#39;s genuinely too wide for one agent to hold coherently, and you&#39;ve been precise enough about the success criteria that a verification agent can actually do its job. Everything else is just expensive theatre.</p>',50)])])}const g=t(i,[["render",r]]);export{p as __pageData,g as default};
